from datetime import datetime, timedelta
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.perf.messenger import send_email_to_tester, get_receivers_for_recovery
from taf.ul.sc.perf.procedure.test_recovery import test_recovery
from taf.ul.sc.perf.util.helpers import round_time_to_seconds, prepare_event_message
from taf.ul.sc.perf.util.test_duration_manager import TestDurationManager
from taf.ul.sc.perf.util.logger import log_info_to_console
from typing import List


class RecoveryObserverManager(object):
    _all_observers: List = []

    def __init__(self, device, events=[]):
        """
        Recovery Observer Manager.
        :param device: moler device
        :param events: list of dict of events to run. eg
            [{event_name='change_state', event_params={'state': 'configured'}}]
        """
        self.device = device
        self.events = events

        self._observers = []
        self._test_recovery_params = None

    def start_recovery_observers(self, action='test_recovery', recovery_params=None, before=None, after=None):
        """
        Start recovery observer.

        :param action: type of recovery. Could be 'test_recovery' or 'break_test'
        :param recovery_params: params for test_recovery
        :param before: list of methods called before recovery
        :param after: list of methods called after recovery
        """

        if action == 'break_test':
            callback_method = self.break_test
            params = {}
        else:
            recovery_params = {} if not recovery_params else recovery_params
            before = self._get_actions_before_recovery(before)
            after = self._get_actions_after_recovery(after)
            callback_method = self.wrapped_test_recovery_callback
            params = {'recovery_params': recovery_params, 'before': before, 'after': after}

        self._start_recovery_observers(callback_method, params)

    def _start_recovery_observers(self, callback_method, params):

        for event in self.events:
            observer = self.device.get_event(**event)
            params['event'] = observer
            observer.add_event_occurred_callback(
                callback=callback_method,
                callback_params=params.copy()
            )

            self._observers.append(observer)
            RecoveryObserverManager._all_observers.append(observer)

            observer.start()

    def stop_recovery_observers(self):
        self._stop_recovery_observers()

    def _stop_recovery_observers(self):
        for observer in self._observers:
            observer.cancel()
        self._observers = []

    def pause_all_recovery_observers(self):
        for observer in RecoveryObserverManager._all_observers:
            observer.pause()

    def resume_all_recovery_observers(self):
        for observer in RecoveryObserverManager._all_observers:
            observer.resume()

    def _get_actions_before_recovery(self, before=None):
        actions = [self.pause_all_recovery_observers]
        if before:
            if isinstance(before, list):
                actions.extend(before)
            else:
                actions.append(before)

        return actions

    def _get_actions_after_recovery(self, after=None):
        actions = [self.resume_all_recovery_observers]
        if after:
            if isinstance(after, list):
                actions.extend(after)
            else:
                actions.append(after)

        return actions

    @MolerTest.raise_background_exceptions()
    def wrapped_test_recovery_callback(self, event, recovery_params={}, before=None, after=None):
        recovery_start = datetime.now()
        recovery_cause = prepare_event_message(event)

        if before:
            for fun in before:
                fun()

        execution_extended = self.__extend_test_duration_if_needed()

        MolerTest.warning(msg=recovery_cause)
        send_email_to_tester(subject="[Moler] Test recovery triggered by event observer",
                             user_message=recovery_cause,
                             receivers=get_receivers_for_recovery(),
                             generate_default_body=True)

        log_info_to_console(msg="Test recovery procedure started", log_hierarchy=2)
        test_recovery(**recovery_params)
        log_info_to_console(msg="Test recovery procedure ended", log_hierarchy=2)

        recovery_duration, execution_end = self.__extend_test_duration(recovery_start, execution_extended)

        msg = """<br>Recovery duration {}
                 <br>Test has been rescheduled and finish at {}""".format(round_time_to_seconds(recovery_duration),
                                                                          round_time_to_seconds(execution_end))

        send_email_to_tester(subject="[Moler] Test recovery ended",
                             user_message=msg,
                             receivers=get_receivers_for_recovery(),
                             generate_default_body=True)

        if after:
            for fun in after:
                fun()

    @staticmethod
    def __extend_test_duration_if_needed():
        execution_extended = False
        if not TestDurationManager().is_time_enough_to_perform_recovery():
            TestDurationManager().extend_test_duration(TestDurationManager.max_recovery_time)
            execution_extended = True

        return execution_extended

    @staticmethod
    def __extend_test_duration(recovery_start, execution_extended):
        recovery_end = datetime.now()
        recovery_duration = recovery_end - recovery_start
        if execution_extended:
            recovery_duration = recovery_duration - timedelta(seconds=TestDurationManager.max_recovery_time)
        execution_end = TestDurationManager().extend_test_duration(recovery_duration.total_seconds())

        return recovery_duration, execution_end

    def break_test(self, event):
        self.pause_all_recovery_observers()

        recovery_cause = prepare_event_message(event)
        MolerTest.warning(msg=recovery_cause)

        subject = "Finishing procedure after detected event"
        log_info_to_console(msg=subject, log_hierarchy=2)

        send_email_to_tester(subject="[Moler] {}".format(subject),
                             user_message=recovery_cause,
                             receivers=get_receivers_for_recovery(),
                             generate_default_body=True)
        TestDurationManager().break_test()
